"""Build the proposed v2 capability model registries and schemas. No vendor calls.

Inputs (reviewed sources, edit these):
  capability-model/source/*.json     families, jurisdictions, assignments, corrections, aliases, fixture adapters
  catalog/providers.json, catalog/provider-capabilities.json, catalog/capabilities.json   (generated by build_bundle.py)

Outputs (generated, do not hand-edit):
  schemas/v2/*.schema.json           v2 record and envelope schemas
  capability-model/registry/*.json   capability definitions, jurisdictions, bindings, legacy crosswalk
  examples/v2/*.json                 illustrative v2 request/result envelopes

Design: ../docs/CANONICAL_EXTERNAL_CAPABILITY_MODEL.md (sections 2-6). Backfill rules: every legacy binding
keeps its lineage, no evidence or readiness is upgraded, every binding stays disabled, quarantine is retained.
Run with --check to verify the checked-in outputs are current without writing.
"""
from pathlib import Path
import hashlib, json, sys

P = Path(__file__).resolve().parent
MODEL_VERSION = '2.0.0'
DEFINITION_VERSION = '1.0.0'
GENERATOR = 'kyc-provider-atlas/build_capability_model.py'

PATH_RE = r'^[a-z][a-z0-9_]*(?:\.[a-z][a-z0-9_]*)*$'
JURISDICTION_RE = r'^(?:[a-z]{2}(?:_[a-z0-9]+)?|global|unresolved)$'
CAPABILITY_ID_RE = r'^[a-z][a-z0-9_]*(?:\.[a-z][a-z0-9_]*)*\.intelligence\.(?:[a-z]{2}(?:_[a-z0-9]+)?|global|unresolved)$'
LIVE_CAPABILITY_ID_RE = r'^[a-z][a-z0-9_]*(?:\.[a-z][a-z0-9_]*)*\.intelligence\.(?:[a-z]{2}(?:_[a-z0-9]+)?|global)$'
KINDS = ['intelligence', 'operational', 'reference', 'testing']
BASES = ['registry_authority', 'issuer_authority', 'dataset_authority', 'policy_jurisdiction', 'financial_source_authority', 'account_servicing', 'integration_scope']
# Section 2.2: the scope fields each basis requires beside the suffix.
BASIS_SCOPE_FIELDS = {
    'registry_authority': ['registry_namespace', 'registration_jurisdiction', 'local_identifier_scheme'],
    'issuer_authority': ['issuing_authority', 'document_identifier_or_credential_type', 'eligible_subject_countries'],
    'dataset_authority': ['publisher_authority', 'dataset_refs', 'applicable_regimes'],
    'policy_jurisdiction': ['policy_jurisdiction', 'source_locations', 'subject_countries', 'legal_report_regime'],
    'financial_source_authority': ['income_source_authority', 'source_institution', 'subject_countries'],
    'account_servicing': ['account_servicing_country', 'account_identifier_namespace', 'source_institution_country'],
    'integration_scope': ['parent_scope_binding_or_global_integration'],
}
ROLES = ['lookup', 'retrieve', 'verify', 'validate', 'derive', 'extract', 'assess', 'screen', 'enrich', 'ingest', 'upload', 'submit', 'control', 'simulate']
NON_PRODUCING_ROLES = ['upload', 'submit', 'control', 'simulate']
OPERATION_KINDS = ['subject_comparison', 'authentication', 'authorization', 'consent', 'subject_resource', 'session', 'webhook', 'health', 'catalog_metadata', 'audit', 'queue',
                   'communication', 'manual_review', 'retention_delete', 'scheduling', 'resource_configuration', 'reconciliation_metadata']
JURISDICTION_KINDS = ['iso_3166_1', 'iso_3166_2_subdivision', 'supranational_authority', 'intergovernmental_authority', 'cross_border_contract', 'unresolved_placeholder']
RESOLUTION_STATUS = ['proposed', 'evidence_supported', 'approved']
COVERAGE_STATUS = ['unknown', 'partial', 'complete', 'not_supported']
MIGRATIONS = ['vocabulary_mapping', 'semantic_correction', 'conditional_split']
SCREENING_FAMILIES = {'screening'}

# ---------------------------------------------------------------- schema helpers
S = {'type': 'string'}
NS = {'type': ['string', 'null']}
ID = {'type': 'string', 'minLength': 1}
B = {'type': 'boolean'}
def obj(props, required=None, extra=False):
    return {'type': 'object', 'properties': props, 'required': list(props) if required is None else list(required), 'additionalProperties': extra}
def arr(items, **kw): return {'type': 'array', 'items': items, **kw}
def enum(values): return {'type': 'string', 'enum': list(values)}
def nenum(values): return {'enum': list(values) + [None]}
def pat(p): return {'type': 'string', 'pattern': p}
def empty_list(): return {'type': 'array', 'maxItems': 0}
def schema(name, title, description, body, defs=None):
    s = {'$schema': 'https://json-schema.org/draft/2020-12/schema', '$id': 'https://kyc-provider-atlas.local/schemas/v2/' + name, 'title': title, 'description': description}
    s.update(body)
    if defs: s['$defs'] = defs
    return s

STRS = arr(S)
SELECTORS = obj({k: STRS for k in ['account_identifier_schemes', 'comparison_fields', 'document_types', 'identifier_schemes', 'registry_namespaces', 'protocols']})

def schemas(families, jurisdiction_tokens, result_kinds):
    paths = sorted(f['capability_path'] for f in families)
    out = {}
    out['jurisdiction.schema.json'] = schema('jurisdiction.schema.json', 'Jurisdiction registry record',
        'A registered canonical jurisdiction token. Unregistered tokens are invalid even when they match the shape.',
        obj({'token': pat(JURISDICTION_RE), 'kind': enum(JURISDICTION_KINDS), 'name': ID, 'iso_3166_1_alpha2': {'type': ['string', 'null'], 'pattern': '^[A-Z]{2}$'},
             'source_native_codes': {'type': 'object', 'additionalProperties': STRS}, 'live_routable_when_approved': B,
             'used_by_binding_count': {'type': 'integer', 'minimum': 0}, 'catalog_market_hints_observed': STRS, 'notes': NS}))
    out['capability-definition.schema.json'] = schema('capability-definition.schema.json', 'CapabilityDefinition',
        'What an interchangeable capability promises (section 3.1). The jurisdiction basis is fixed per definition and cannot vary between bindings.',
        obj({'capability_path': pat(PATH_RE), 'model_version': {'const': MODEL_VERSION}, 'definition_version': pat(r'^\d+\.\d+\.\d+$'),
             'status': enum(['proposed', 'approved', 'deprecated']), 'group': enum(['legacy_compatible', 'native_inventory_addition']),
             'kind': enum(KINDS), 'jurisdiction_basis': enum(BASES), 'required_scope_fields': arr(S, minItems=1), 'subject_types': arr(ID, minItems=1),
             'default_action': ID, 'allowed_actions': arr(ID, minItems=1), 'result_family': ID, 'result_family_status': enum(['existing_host_union', 'proposed_schema']),
             'definition': ID, 'input_schema_ref': NS, 'output_schema_ref': NS, 'schema_status': enum(['not_defined', 'draft', 'approved']),
             'success_semantics': ID, 'invariants': arr(ID, minItems=1), 'not_substitutable_for': arr(enum(paths)), 'legacy_aliases': STRS,
             'owner': NS, 'governance': obj({'approval_ref': NS, 'blockers': STRS})}))
    out['provider-capability-binding.schema.json'] = schema('provider-capability-binding.schema.json', 'ProviderCapabilityBinding',
        'Who can supply which scoped contract (section 3.2). Coverage evidence, transport, field mapping and execution authorization are independent. '
        'An unresolved jurisdiction, quarantine or empty approved scope blocks live resolution.',
        {**obj({'binding_id': pat(r'^binding:[a-z0-9-]+:[a-z0-9_.]+:v[0-9]+$'), 'provider_record_id': ID, 'provider_family_id': NS, 'contracting_entity_id': NS, 'product_id': NS,
                'capability_id': pat(CAPABILITY_ID_RE), 'capability_path': enum(paths), 'capability_definition_ref': pat(r'^[a-z0-9_.]+@\d+\.\d+\.\d+$'),
                'model_version': {'const': MODEL_VERSION}, 'actions': arr(ID, minItems=1), 'subject_types': arr(ID, minItems=1), 'selectors': SELECTORS,
                'jurisdiction': obj({'code': enum(jurisdiction_tokens), 'basis': enum(BASES), 'resolution_status': enum(RESOLUTION_STATUS),
                                     'assignment_basis': enum(['no_evidence', 'national_source_hint', 'publisher_authority', 'federation_unresolved']), 'evidence_refs': STRS}),
                'coverage': obj({'status': enum(COVERAGE_STATUS), 'eligible_subject_countries': STRS, 'eligible_account_countries': STRS, 'issuing_authorities': STRS,
                                 'dataset_refs': STRS, 'excluded_scopes': STRS, 'freshness_policy_ref': NS, 'assessed_at': NS, 'coverage_evidence_refs': STRS}),
                'operation_mapping_refs': STRS,
                'versions': obj({k: NS for k in ['native_api', 'native_schema_digest', 'adapter', 'request_mapping', 'response_mapping', 'host_schema']}),
                'implementation': obj({'transport': enum(['not_implemented', 'documented_unverified', 'host_native_subset_unverified', 'sandbox_accepted', 'production']),
                                       'request_mapping': enum(['not_defined', 'proposed', 'legacy_v1_offline_planner', 'validated']),
                                       'response_mapping': enum(['not_defined', 'proposed', 'legacy_v1_fixture_subset', 'fixture_tested_subset', 'validated']),
                                       'validation': enum(['none', 'legacy_v1_synthetic_fixture', 'synthetic_fixture', 'sandbox', 'production']),
                                       'v2_validated': B, 'accepted_test_evidence_refs': STRS}),
                'access': obj({**{k: STRS for k in ['tenant_ids', 'environments', 'allowed_purposes', 'policy_refs', 'approved_endpoints', 'processing_regions', 'storage_regions', 'permitted_dataset_refs']},
                               **{k: NS for k in ['entitlement_ref', 'consent_requirement_ref', 'secret_ref']}}),
                'governance': obj({'enabled': B, 'approval_ref': NS, 'quarantine': B, 'blockers': STRS}),
                'lineage': obj({'legacy_binding_id': ID, 'legacy_capability': ID, 'legacy_result_family': ID, 'legacy_mapping_maturity': ID, 'legacy_status': ID,
                                'legacy_adapter_id': NS, 'migration': enum(MIGRATIONS), 'conditional_branch': {'type': ['object', 'null']}, 'correction_reason': NS, 'source_file': ID})}),
         'allOf': [
             # Live execution requires a resolved, approved jurisdiction and no quarantine.
             {'if': {'properties': {'governance': {'properties': {'enabled': {'const': True}}}}},
              'then': {'properties': {'capability_id': pat(LIVE_CAPABILITY_ID_RE), 'jurisdiction': {'properties': {'resolution_status': {'const': 'approved'}}},
                                      'governance': {'properties': {'quarantine': {'const': False}, 'blockers': empty_list()}}}}},
             {'if': {'properties': {'jurisdiction': {'properties': {'code': {'const': 'unresolved'}}}}},
              'then': {'properties': {'governance': {'properties': {'enabled': {'const': False}, 'blockers': {'contains': {'const': 'jurisdiction_unresolved'}}}}}}},
         ]})
    out['native-operation-mapping.schema.json'] = schema('native-operation-mapping.schema.json', 'NativeOperationMapping',
        'What one vendor call actually does (section 3.3). The role describes the operation; upload, submit, control and simulate never produce a completed check outcome.',
        {**obj({'operation_mapping_id': pat(r'^operation-map:[a-z0-9-]+:[A-Za-z0-9_.-]+:v[0-9]+$'), 'vendor_definition_id': ID, 'provider_record_id': ID,
                'provider_identity_relationship': enum(['same_id', 'proposed_alias']), 'native_operation_id': ID, 'native_method': enum(['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'HEAD']),
                'native_path': ID, 'native_api_version': NS, 'native_semantics_original': ID, 'primary_capability_path': enum(paths), 'capability_id': pat(CAPABILITY_ID_RE),
                'jurisdiction': obj({'code': enum(jurisdiction_tokens), 'source': enum(['binding_required', 'native_source_hint', 'publisher_authority'])}),
                'operation_role': enum(ROLES), 'operation_kind': nenum(OPERATION_KINDS), 'mapping_relation': enum(['proposed_semantic_mapping', 'validated_mapping']),
                'rationale': ID, 'mapping_evidence_refs': STRS, 'request_schema_ref': NS, 'response_schema_ref': NS, 'request_mapping_ref': NS, 'response_mapping_ref': NS,
                'preconditions': STRS, 'enables': STRS, 'produces': STRS,
                'conditional_dispatch': arr(obj({'when': {'type': 'object'}, 'capability_path': enum(paths), 'subject_types': arr(ID, minItems=1), 'request_schema_ref': NS, 'response_schema_ref': NS})),
                'dispatch_status': enum(['not_required', 'required_unconfigured', 'configured']), 'status': enum(['proposed', 'blocked', 'approved']), 'blockers': STRS,
                'candidate_binding_refs': STRS, 'live_tested': B,
                'lineage': obj({'review_source': ID, 'definition_file': ID, 'definition_sha256': pat('^[0-9a-f]{64}$')})}),
         'allOf': [
             {'if': {'properties': {'operation_role': enum(NON_PRODUCING_ROLES)}}, 'then': {'properties': {'produces': empty_list()}}},
             {'if': {'properties': {'primary_capability_path': {'const': 'platform.testing'}}}, 'then': {'properties': {'operation_role': {'const': 'simulate'}}}},
             {'if': {'properties': {'dispatch_status': {'const': 'required_unconfigured'}}}, 'then': {'properties': {'status': {'const': 'blocked'}, 'produces': empty_list()}}},
             {'if': {'properties': {'status': {'const': 'approved'}}}, 'then': {'properties': {'mapping_relation': {'const': 'validated_mapping'}, 'blockers': empty_list(),
                                                                                               'jurisdiction': {'properties': {'code': {'not': {'const': 'unresolved'}}}}}}},
         ]})
    out['legacy-binding-crosswalk.schema.json'] = schema('legacy-binding-crosswalk.schema.json', 'Legacy binding crosswalk record',
        'How one v1 provider:capability binding maps to v2 bindings. Corrected entries are not reversible aliases.',
        obj({'legacy_binding_id': pat(r'^[a-z0-9-]+:[a-z0-9_.]+$'), 'provider_record_id': ID, 'legacy_capability': ID, 'legacy_result_family': ID, 'migration': enum(MIGRATIONS),
             'binding_ids': arr(ID, minItems=1), 'capability_ids': arr(pat(CAPABILITY_ID_RE), minItems=1),
             'legacy_runtime_disposition': enum(['alias_pending_approval', 'migration_required', 'quarantined']), 'note': ID}))
    out['registry-envelope.schema.json'] = schema('registry-envelope.schema.json', 'Capability model registry file',
        'Envelope for generated registry files. Records are validated by their record schema; sources pin the inputs the file was built from.',
        obj({'registry': enum(['capability_definitions', 'jurisdictions', 'capability_bindings', 'legacy_crosswalk', 'operation_mappings']),
             'model_version': {'const': MODEL_VERSION}, 'record_schema': ID, 'generated_by': ID, 'status': {'const': 'proposed_not_enabled'},
             'sources': arr(obj({'path': ID, 'sha256': pat('^[0-9a-f]{64}$')}), minItems=1), 'record_count': {'type': 'integer', 'minimum': 0},
             'records': {'type': 'array'}, 'vocabulary': {'type': 'array'}, 'fixture_adapters': {'type': 'array'}, 'provider_aliases': {'type': 'array'}, 'version_conflicts': {'type': 'array'},
             'binding_index': {'type': 'object', 'additionalProperties': arr(ID, minItems=1)}},
            required=['registry', 'model_version', 'record_schema', 'generated_by', 'status', 'sources', 'record_count', 'records']))
    # Section 3.4 envelopes. Per-capability input/output schemas are still to be defined, so input and result are open objects.
    routing = obj({'provider_allowlist': STRS, 'binding_allowlist': STRS, 'permitted_processing_regions': STRS, 'permitted_storage_regions': STRS, 'fallback_policy_ref': NS})
    # Section 3.3/5.1 rule 8: native controls return typed receipts with no checked scope or assertions.
    out['operation-receipt.schema.json'] = schema('operation-receipt.schema.json', 'Operation receipt',
        'Typed record of a native operation that does not produce an intelligence result: controls, uploads, simulations, blocked mappings and families '
        'the v1 host envelope cannot represent. A successful receipt is never a completed check, approval or screening clearance.',
        obj({'receipt_id': ID, 'request_id': ID, 'tenant_id': ID, 'subject_entity_id': ID, 'operation_mapping_id': pat(r'^operation-map:[a-z0-9-]+:[A-Za-z0-9_.-]+:v[0-9]+$'),
             'vendor_definition_id': ID, 'provider_record_id': ID, 'native_operation_id': ID, 'native_api_version': NS,
             'capability_id': pat(CAPABILITY_ID_RE), 'primary_capability_path': enum(paths), 'operation_role': enum(ROLES), 'operation_kind': nenum(OPERATION_KINDS),
             'receipt_reason': enum(['control_operation', 'upload_operation', 'synthetic_test_operation', 'mapping_blocked', 'no_v1_capability_contract']),
             'execution': obj({'status': enum(['completed', 'pending', 'failed']), 'http_status': {'type': ['integer', 'null']}, 'received_at': {'type': 'string', 'format': 'date-time'}}),
             'native_status_original': NS, 'provider_resource_ref': NS, 'produces_intelligence': {'const': False}, 'synthetic': B,
             'assertions': empty_list(), 'checked_scope': empty_list(), 'enables': STRS,
             'mapping': obj({'status': enum(['proposed', 'blocked', 'approved']), 'mapping_relation': enum(['proposed_semantic_mapping', 'validated_mapping']), 'blockers': STRS, 'model_version': ID}),
             'raw_payload': obj({'vault_ref': ID, 'sha256': pat('^[0-9a-f]{64}$'), 'classification': {'const': 'restricted'}}),
             'warnings': STRS, 'errors': arr(obj({'code': ID, 'message': ID}))}))
    out['capability-request.schema.json'] = schema('capability-request.schema.json', 'CanonicalCapabilityRequest v2 (draft)',
        'Provider-independent request envelope. unresolved is not a requestable jurisdiction. The input object is validated by the capability definition input schema once defined.',
        obj({'request_id': ID, 'tenant_id': ID, 'capability_id': pat(LIVE_CAPABILITY_ID_RE), 'capability_definition_version': pat(r'^\d+\.\d+\.\d+$'), 'action': ID,
             'subject_entity_id': ID, 'input': {'type': 'object'},
             'scope': obj({'requested_jurisdictions': arr(pat(r'^(?:[a-z]{2}(?:_[a-z0-9]+)?|global)$'), minItems=1), 'requested_dataset_refs': STRS, 'subject_countries': STRS,
                           'as_of': NS, 'freshness_policy_ref': NS}),
             'purpose': ID, 'policy_ref': ID, 'consent_ref': NS, 'routing': routing, 'idempotency_key': ID}))
    out['capability-result.schema.json'] = schema('capability-result.schema.json', 'CanonicalCapabilityResult v2 (draft)',
        'Result envelope. Execution, assessment, coverage, evidence status and institution decision are independent. The result payload is validated by the definition output schema once defined.',
        {**obj({'result_id': ID, 'request_id': ID, 'tenant_id': ID, 'capability_id': pat(LIVE_CAPABILITY_ID_RE), 'capability_definition_version': pat(r'^\d+\.\d+\.\d+$'),
                'binding_id': ID, 'operation_mapping_id': ID, 'execution': obj({'status': enum(['pending', 'completed', 'failed', 'reconciliation_required'])}),
                'assessment': obj({'outcome': enum(['unknown', 'not_checked', 'inconclusive', 'matched', 'not_matched', 'not_applicable']), 'provider_outcome_original': NS,
                                   'bank_decision': {'const': 'not_evaluated'}}),
                'coverage': obj({'status': enum(COVERAGE_STATUS), 'requested_scope': STRS, 'checked_scope': STRS, 'not_checked_scope': STRS, 'dataset_versions': STRS, 'reason_codes': STRS}),
                'result': {'type': 'object', 'required': ['kind'], 'properties': {'kind': enum(result_kinds)}},
                'assertions': {'type': 'array'}, 'relationships': {'type': 'array'}, 'evidence_refs': STRS, 'raw_payload_ref': NS, 'warnings': STRS}),
         'allOf': [{'if': {'properties': {'execution': {'properties': {'status': {'enum': ['pending', 'failed', 'reconciliation_required']}}}}},
                    'then': {'properties': {'assertions': empty_list(), 'assessment': {'properties': {'outcome': {'enum': ['unknown', 'not_checked']}}}}}},
                   {'if': {'properties': {'coverage': {'properties': {'status': {'const': 'complete'}}}}},
                    'then': {'properties': {'coverage': {'properties': {'not_checked_scope': empty_list()}}}}}]})
    return out

# ---------------------------------------------------------------- registry builders
def read(rel): return json.loads((P / rel).read_text())
def sha(rel): return hashlib.sha256((P / rel).read_bytes()).hexdigest()
def dumps(o): return json.dumps(o, indent=2, ensure_ascii=False) + '\n'

def invariants(f):
    inv = ['technical_success_is_not_verification_success', 'institution_decision_not_evaluated_in_adapter_layer',
           'unresolved_jurisdiction_is_not_live_routable', 'empty_scope_lists_mean_none_established', 'findings_reference_source_evidence_and_mapping_version']
    if f['kind'] in ('operational', 'testing'):
        inv.append('control_success_produces_no_intelligence_assertion')
    if f['kind'] == 'testing':
        inv.append('results_are_synthetic_and_never_satisfy_live_requirements')
    if f['kind'] == 'reference':
        inv.append('reference_data_is_not_a_subject_check_outcome')
    if f['result_family'] == 'screening':
        inv.append('empty_candidate_list_is_not_legal_clearance')
    if f['result_family'] == 'ownership':
        inv.append('missing_edges_do_not_establish_absence_of_beneficial_owner')
    if f['result_family'] == 'risk':
        inv.append('native_score_scales_not_comparable_without_governed_transformation')
    if f['capability_path'] in ('screening.watchlist', 'workflow.orchestration', 'business.verification'):
        inv.append('composite_results_preserve_child_capability_ids_and_coverage')
    if f['capability_path'] == 'screening.sanctions':
        inv.append('dataset_publisher_does_not_restrict_subject_nationality')
    if f['not_substitutable_for']:
        inv.append('cannot_satisfy_listed_non_substitutable_contracts')
    return inv

SUCCESS = {'verify': 'check_executed', 'validate': 'check_executed', 'screen': 'screening_executed_within_declared_scope', 'assess': 'assessment_returned_with_methodology',
           'lookup': 'records_retrieved_within_declared_scope', 'retrieve': 'records_retrieved_within_declared_scope', 'discover': 'edges_returned_with_completeness_statement',
           'monitor': 'evaluation_executed_for_declared_window', 'resolve': 'candidates_returned_without_automatic_merge', 'ingest': 'versioned_snapshot_acquired',
           'extract': 'fields_extracted_with_source_pointers', 'derive': 'derivation_computed_not_validated'}

def build_definitions(families):
    recs = []
    for f in families:
        recs.append({'capability_path': f['capability_path'], 'model_version': MODEL_VERSION, 'definition_version': DEFINITION_VERSION, 'status': 'proposed', 'group': f['group'],
                     'kind': f['kind'], 'jurisdiction_basis': f['jurisdiction_basis'], 'required_scope_fields': BASIS_SCOPE_FIELDS[f['jurisdiction_basis']],
                     'subject_types': f['subject_types'], 'default_action': f['default_action'], 'allowed_actions': [f['default_action']],
                     'result_family': f['result_family'], 'result_family_status': f['result_family_status'], 'definition': f['definition'],
                     'input_schema_ref': None, 'output_schema_ref': None, 'schema_status': 'not_defined',
                     'success_semantics': SUCCESS.get(f['default_action'], 'operation_receipt_only' if f['kind'] in ('operational', 'testing') else 'contract_specific'),
                     'invariants': invariants(f), 'not_substitutable_for': f['not_substitutable_for'], 'legacy_aliases': [f['legacy_capability']] if f['legacy_capability'] else [],
                     'owner': None, 'governance': {'approval_ref': None, 'blockers': ['owner_unassigned', 'input_output_schemas_not_defined', 'definition_not_approved']}})
    return recs

def binding_record(b, prov, fam, path, jur, migration, branch, correction, fixture):
    capability_id = f'{path}.intelligence.{jur["jurisdiction"]}'
    vocab = migration == 'vocabulary_mapping'
    fx = fixture if vocab else None   # fixture evidence never carries over to corrected semantics
    quarantined = b['status'].startswith('quarantined') or prov['routing_eligibility'].startswith('quarantined')
    blockers = ['jurisdiction_unresolved' if jur['jurisdiction'] == 'unresolved' else 'jurisdiction_not_approved', 'coverage_unknown', 'contracting_entity_unresolved',
                'entitlement_missing', 'capability_schemas_not_defined', 'native_operation_mapping_missing', 'request_response_mapping_missing', 'sandbox_acceptance_missing', 'approval_missing']
    if migration == 'semantic_correction': blockers.append('semantic_correction_review_required')
    if migration == 'conditional_split': blockers.append('conditional_split_review_required')
    if quarantined: blockers.append('provider_quarantined')
    sel = {k: [] for k in ['account_identifier_schemes', 'comparison_fields', 'document_types', 'identifier_schemes', 'registry_namespaces', 'protocols']}
    if branch: sel.update(branch['selector'])
    return {
        'binding_id': f'binding:{b["provider_id"]}:{capability_id}:v1', 'provider_record_id': b['provider_id'], 'provider_family_id': prov.get('family_id'),
        'contracting_entity_id': None, 'product_id': None, 'capability_id': capability_id, 'capability_path': path,
        'capability_definition_ref': f'{path}@{DEFINITION_VERSION}', 'model_version': MODEL_VERSION, 'actions': [fam['default_action']], 'subject_types': fam['subject_types'],
        'selectors': sel,
        'jurisdiction': {'code': jur['jurisdiction'], 'basis': fam['jurisdiction_basis'], 'resolution_status': 'proposed', 'assignment_basis': jur['assignment_basis'], 'evidence_refs': []},
        'coverage': {'status': 'unknown', 'eligible_subject_countries': [], 'eligible_account_countries': [], 'issuing_authorities': [], 'dataset_refs': [], 'excluded_scopes': [],
                     'freshness_policy_ref': None, 'assessed_at': None, 'coverage_evidence_refs': []},
        'operation_mapping_refs': [],
        'versions': {k: None for k in ['native_api', 'native_schema_digest', 'adapter', 'request_mapping', 'response_mapping', 'host_schema']},
        'implementation': {'transport': 'host_native_subset_unverified' if fx and fx['host_native_connector'] else 'not_implemented',
                           'request_mapping': 'legacy_v1_offline_planner' if fx and fx['offline_planner'] else 'not_defined',
                           'response_mapping': 'legacy_v1_fixture_subset' if fx else 'not_defined',
                           'validation': 'legacy_v1_synthetic_fixture' if fx else 'none', 'v2_validated': False, 'accepted_test_evidence_refs': []},
        'access': {'tenant_ids': [], 'environments': [], 'allowed_purposes': [], 'policy_refs': [], 'entitlement_ref': None, 'consent_requirement_ref': None, 'secret_ref': None,
                   'approved_endpoints': [], 'processing_regions': [], 'storage_regions': [], 'permitted_dataset_refs': []},
        'governance': {'enabled': False, 'approval_ref': None, 'quarantine': quarantined, 'blockers': blockers},
        'lineage': {'legacy_binding_id': b['operation_id'], 'legacy_capability': b['capability'], 'legacy_result_family': b['result_family'],
                    'legacy_mapping_maturity': b['mapping_maturity'], 'legacy_status': b['status'], 'legacy_adapter_id': b['adapter_id'], 'migration': migration,
                    'conditional_branch': {'condition': branch['condition'], 'selector': branch['selector']} if branch else None,
                    'correction_reason': correction['reason'] if correction else None, 'source_file': 'kyc-provider-atlas/catalog/provider-capabilities.json'},
    }

def build():
    src = {n: read(f'capability-model/source/{n}.json') for n in ['families', 'jurisdictions', 'jurisdiction-assignments', 'semantic-corrections', 'provider-aliases', 'fixture-adapters']}
    families = src['families']['families']
    fam = {f['capability_path']: f for f in families}
    legacy_to_path = {f['legacy_capability']: f['capability_path'] for f in families if f['legacy_capability']}
    providers = {p['provider_id']: p for p in read('catalog/providers.json')}
    legacy_bindings = read('catalog/provider-capabilities.json')
    legacy_caps = [c['capability'] for c in read('catalog/capabilities.json')]
    assert set(legacy_caps) == set(legacy_to_path), 'every legacy capability needs exactly one family'
    corrections = {(c['provider_id'], c['legacy_capability']): c for c in src['semantic-corrections']['corrections']}
    assign = src['jurisdiction-assignments']
    fixtures = {f['provider_id']: f for f in src['fixture-adapters']['adapters']}
    tokens = {j['token']: j for j in src['jurisdictions']['jurisdictions']}

    bindings, crosswalk = [], []
    for b in legacy_bindings:
        prov = providers[b['provider_id']]
        jur = assign['assignments'].get(b['provider_id'], assign['default'])
        assert jur['jurisdiction'] in tokens, jur
        corr = corrections.get((b['provider_id'], b['capability']))
        fixture = fixtures.get(b['provider_id']) if b['adapter_id'] else None
        if fixture: assert fixture['legacy_capability'] == b['capability'] and fixture['adapter_id'] == b['adapter_id']
        if corr and corr['migration'] == 'conditional_split':
            targets = [(br['capability_path'], 'conditional_split', br) for br in corr['branches']]
        elif corr:
            assert len(corr['capability_paths']) == 1
            targets = [(corr['capability_paths'][0], 'semantic_correction', None)]
        else:
            targets = [(legacy_to_path[b['capability']], 'vocabulary_mapping', None)]
        recs = [binding_record(b, prov, fam[path], path, jur, mig, br, corr, fixture) for path, mig, br in targets]
        bindings += recs
        quarantined = any(r['governance']['quarantine'] for r in recs)
        crosswalk.append({'legacy_binding_id': b['operation_id'], 'provider_record_id': b['provider_id'], 'legacy_capability': b['capability'], 'legacy_result_family': b['result_family'],
                          'migration': targets[0][1], 'binding_ids': [r['binding_id'] for r in recs], 'capability_ids': [r['capability_id'] for r in recs],
                          'legacy_runtime_disposition': 'quarantined' if quarantined else 'alias_pending_approval' if targets[0][1] == 'vocabulary_mapping' else 'migration_required',
                          'note': corr['note'] if corr else 'Legacy semantic proposal retained; support must be established per binding.'})
    ids = [r['binding_id'] for r in bindings]
    assert len(ids) == len(set(ids)), 'binding IDs must be unique'
    assert set(c['provider_id'] for c in corrections.values()) <= set(providers) and len(corrections) == sum(1 for x in crosswalk if x['migration'] != 'vocabulary_mapping')

    used = {}
    for r in bindings: used[r['jurisdiction']['code']] = used.get(r['jurisdiction']['code'], 0) + 1
    hints = {}
    for pid, a in assign['assignments'].items():
        if a['jurisdiction'] != 'unresolved': hints.setdefault(a['jurisdiction'], set()).add(a['catalog_market_hint'])
    jrecs = [{**j, 'used_by_binding_count': used.get(j['token'], 0), 'catalog_market_hints_observed': sorted(hints.get(j['token'], []))} for j in src['jurisdictions']['jurisdictions']]
    jrecs = [{k: r[k] for k in ['token', 'kind', 'name', 'iso_3166_1_alpha2', 'source_native_codes', 'live_routable_when_approved', 'used_by_binding_count', 'catalog_market_hints_observed', 'notes']} for r in jrecs]

    vocabulary = [{'legacy_capability': c, 'capability_path': legacy_to_path[c], 'capability_template': legacy_to_path[c] + '.intelligence.[jurisdiction]',
                   'corrected_bindings': sorted(x['legacy_binding_id'] for x in crosswalk if x['legacy_capability'] == c and x['migration'] != 'vocabulary_mapping')} for c in legacy_caps]
    fixture_adapters = []
    for f in src['fixture-adapters']['adapters']:
        lid = f'{f["provider_id"]}:{f["legacy_capability"]}'
        bid = next(x for x in crosswalk if x['legacy_binding_id'] == lid)['binding_ids']
        assert [f['proposed_capability_id']] == next(x for x in crosswalk if x['legacy_binding_id'] == lid)['capability_ids']
        fixture_adapters.append({**f, 'legacy_binding_id': lid, 'binding_ids': bid})

    srcs = lambda paths: [{'path': p, 'sha256': sha(p)} for p in paths]
    common_src = ['capability-model/source/families.json']
    result_kinds = sorted({f['result_family'] for f in families})
    sch = schemas(families, sorted(tokens), result_kinds)
    def env(name, schema_name, records, inputs, **extra):
        return {'registry': name, 'model_version': MODEL_VERSION, 'record_schema': 'schemas/v2/' + schema_name, 'generated_by': GENERATOR, 'status': 'proposed_not_enabled',
                'sources': srcs(inputs), 'record_count': len(records), 'records': records, **extra}
    binding_inputs = common_src + ['capability-model/source/jurisdictions.json', 'capability-model/source/jurisdiction-assignments.json', 'capability-model/source/semantic-corrections.json',
                                   'capability-model/source/fixture-adapters.json', 'catalog/providers.json', 'catalog/provider-capabilities.json']
    out = {f'schemas/v2/{k}': dumps(v) for k, v in sch.items()}
    out['capability-model/registry/capability-definitions.json'] = dumps(env('capability_definitions', 'capability-definition.schema.json', build_definitions(families), common_src + ['catalog/capabilities.json']))
    out['capability-model/registry/jurisdictions.json'] = dumps(env('jurisdictions', 'jurisdiction.schema.json', jrecs, ['capability-model/source/jurisdictions.json', 'capability-model/source/jurisdiction-assignments.json', 'catalog/provider-capabilities.json']))
    out['capability-model/registry/capability-bindings.json'] = dumps(env('capability_bindings', 'provider-capability-binding.schema.json', bindings, binding_inputs))
    out['capability-model/registry/legacy-crosswalk.json'] = dumps(env('legacy_crosswalk', 'legacy-binding-crosswalk.schema.json', crosswalk, binding_inputs + ['capability-model/source/provider-aliases.json', 'catalog/capabilities.json'],
                                                                       vocabulary=vocabulary, fixture_adapters=fixture_adapters, provider_aliases=src['provider-aliases']['aliases'],
                                                                       version_conflicts=src['provider-aliases']['version_conflicts']))
    out.update(examples())
    return out

def examples():
    # Section 3.4 illustrations: envelope structure only, no findings or evidence; not accepted fixtures.
    req = {'request_id': 'req-001', 'tenant_id': 'tenant-001', 'capability_id': 'business.registry.intelligence.gb', 'capability_definition_version': '1.0.0', 'action': 'lookup',
           'subject_entity_id': 'organization-001', 'input': {'identifier': {'scheme': 'company_registration', 'jurisdiction': 'gb', 'value': '01234567'}, 'registry_namespace': 'companies_house'},
           'scope': {'requested_jurisdictions': ['gb'], 'requested_dataset_refs': ['companies_house_company_profile'], 'subject_countries': [], 'as_of': None, 'freshness_policy_ref': 'registry-current'},
           'purpose': 'customer_due_diligence', 'policy_ref': 'policy:kyb:version-1', 'consent_ref': None,
           'routing': {'provider_allowlist': ['companies-house'], 'binding_allowlist': [], 'permitted_processing_regions': [], 'permitted_storage_regions': [], 'fallback_policy_ref': None},
           'idempotency_key': 'req-001'}
    res = {'result_id': 'res-001', 'request_id': 'req-001', 'tenant_id': 'tenant-001', 'capability_id': 'business.registry.intelligence.gb', 'capability_definition_version': '1.0.0',
           'binding_id': 'binding:companies-house:business.registry.intelligence.gb:v1', 'operation_mapping_id': 'operation-map:companies-house:get_company_companynumber:v1',
           'execution': {'status': 'completed'}, 'assessment': {'outcome': 'not_applicable', 'provider_outcome_original': None, 'bank_decision': 'not_evaluated'},
           'coverage': {'status': 'partial', 'requested_scope': ['company_profile', 'beneficial_owners'], 'checked_scope': ['company_profile'], 'not_checked_scope': ['beneficial_owners'],
                        'dataset_versions': [], 'reason_codes': ['ownership_not_requested_from_source']},
           'result': {'kind': 'business', 'organization_entity_id': 'organization-001'}, 'assertions': [], 'relationships': [], 'evidence_refs': [], 'raw_payload_ref': None, 'warnings': []}
    return {'examples/v2/capability-request.json': dumps(req), 'examples/v2/capability-result.json': dumps(res)}

def main(argv):
    out = build()
    stale = [k for k, v in out.items() if not (P / k).exists() or (P / k).read_text() != v]
    if '--check' in argv:
        if stale: print('Stale generated files:\n  ' + '\n  '.join(stale)); return 1
        print('Capability model outputs are current (%d files).' % len(out)); return 0
    for k in stale:
        (P / k).parent.mkdir(parents=True, exist_ok=True); (P / k).write_text(out[k])
    reg = json.loads(out['capability-model/registry/capability-bindings.json'])
    print('Wrote %d of %d files; %d bindings, %d enabled.' % (len(stale), len(out), reg['record_count'], sum(r['governance']['enabled'] for r in reg['records'])))
    return 0

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
